def calculate_N(m):
    if m <= 1:
        return 0

    S = list(range(1, m))
    visited = [False] * m
    N = 0

    for x in S:
        if not visited[x]:
            N += 1
            current = x
            # Trace the cycle
            # We rely on the fact that 3x mod m != 0 since 3 doesn't divide m
            while not visited[current]:
                visited[current] = True
                current = (3 * current) % m
    return N

candidates = []
limit = 200

# Iterate downwards to find the largest candidates first
for m in range(limit - 1, 0, -1):
    if m % 3 == 0:
        continue

    N_m = calculate_N(m)

    if N_m % 2 != 0:
        candidates.append(m)

# Sort in descending order (they should already be in descending order due to the loop)
# candidates.sort(reverse=True) 

if len(candidates) >= 2:
    second_largest = candidates[1]
    print(f"Candidates found (descending): {candidates}")
    print(f"Second largest m such that N(m) is odd is: {second_largest}")
else:
    print("Not enough candidates found.")
